export const allCounties: USCounty[] = Object.values(COMPACT_DB).flat();

export function getCountiesByState(stateAbbreviation: string): USCounty[] {
  return COMPACT_DB[stateAbbreviation.toUpperCase()] || [];
}

export function getCountyByFips(fips: string): USCounty | undefined {
  return allCounties.find(c => c.fips === fips);
}

export function getCountyByStateAndName(stateAbbreviation: string, countyName: string): USCounty | undefined {
  const list = COMPACT_DB[stateAbbreviation.toUpperCase()] || [];
  const normName = countyName.toLowerCase().replace(/\s+(county|parish|borough|census area|municipality|city)$/i, '').trim();
  return list.find(c => {
    const normC = c.countyName.toLowerCase();
    const normFull = c.countyFullName.toLowerCase().replace(/\s+(county|parish|borough|census area|municipality|city)$/i, '').trim();
    return normC === normName || normFull === normName;
  });
}

// Backwards compatibility functions
export function getStatesList() {
  return allStates;
}
export function getCountiesForState(stateCode: string) {
  return getCountiesByState(stateCode);
}
export function getCountyData(stateCode: string, countyName: string) {
  return getCountyByStateAndName(stateCode, countyName);
}
export function searchCounties(query: string, stateCode?: string) {
  const cleanQuery = query.toLowerCase().trim();
  if (!cleanQuery) return [];
  const source = stateCode ? getCountiesByState(stateCode) : allCounties;
  return source.filter(c => 
    c.countyName.toLowerCase().includes(cleanQuery) || 
    c.countyFullName.toLowerCase().includes(cleanQuery)
  ).slice(0, 50);
}
export function getCountyCentroid(stateCode: string, countyName: string) {
  return getCountyByStateAndName(stateCode, countyName)?.centroid;
}
export function getCountyBBox(stateCode: string, countyName: string) {
  return getCountyByStateAndName(stateCode, countyName)?.bbox;
}
